1	#!/usr/bin/env node
2	// The Claudinite SELF-TEST — "can Claudinite run here?", and nothing else.
3	//
4	// Deliberately NOT a conformance check. `check_the_world` judges the repo's
5	// CONTENT against the rules; this judges whether the MACHINERY that would run
6	// those rules is intact. A repo can be perfectly conformant and still have a
7	// broken mount, a hook pointing at a file that no longer exists, or a pack whose
8	// manifest the loader silently drops — and every one of those is invisible to a
9	// content check, because a rule that never runs reports nothing.
10	//
11	// WHY IT EXISTS. Every fleet-wide failure this corpus has had was of that shape:
12	//
13	//   #397  inject-pack-prose imported a module that did not exist, so every
14	//         active pack's RULES.md was silently un-injected, fleet-wide, for days
15	//   #518  loadConfig dropped the mount stamp, so the nightly converge self-skipped
16	//         everywhere and no run ever said so
17	//   #555  a required manifest field landed with no migration; consumer packs
18	//         stopped validating, and (because normalizeManifest rebuilds `rules`
19	//         from the scoped lists) their checks stopped running silently
20	//   #424  five mounted skill links dangled on main, unnoticed
21	//
22	// None was caught by canon CI, because the canon's own tree is always already
23	// correct. All four are assertions below, and each would have fired on the first
24	// session after the change — on the member, where the damage was.
25	//
26	// CONTRACT. Fast (no network, no clone), read-only, and it never throws: a probe
27	// that cannot run is a FAILED probe with the reason attached, never a crash that
28	// takes the session-start orchestrator down with it.
29	//
30	// Pure core + thin I/O shell, the corpus idiom: `report()` takes plain probe
31	// results and decides the outcome, so the whole decision surface is testable
32	// without a repo on disk.
33	
34	import { existsSync, readFileSync, readdirSync, lstatSync, realpathSync } from 'node:fs';
35	import { join, dirname } from 'node:path';
36	import { fileURLToPath, pathToFileURL } from 'node:url';
37	import { SETTINGS_FILE, SETTINGS_FILES } from './settings-file.mjs';
38	import { hasInstalledMount } from './installed-versions.mjs';
39	
40	export const MOUNT = '.claudinite/shared';
41	// Both settings-file names, newest first (#1252): the probe runs on a member whose
42	// own rename record may not have landed yet, and reporting "the declaration is
43	// missing" on a repo that simply spells it the old way would fail every session
44	// there over a file sitting right beside it.
45	export const CHECKS = SETTINGS_FILE;
46	export const SETTINGS = '.claude/settings.json';
47	export const SCHEDULER = '.github/workflows/claudinite-scheduler.yml';
48	
49	// A probe result. `ok: null` means NOT APPLICABLE — the thing this probe would
50	// judge is legitimately absent (no scheduler in a repo that never cut over, no
51	// local packs declared). Not-applicable is never a failure; conflating the two
52	// is how a check earns its reputation for crying wolf.
53	export const pass = (id) => ({ id, ok: true });
54	export const skip = (id, why) => ({ id, ok: null, detail: why });
55	export const fail = (id, detail, fix) => ({ id, ok: false, detail, fix });
56	
57	// The verdict over a probe set. Exit code is the caller's business — this only
58	// says what happened, so both callers (a session-start step that must never
59	// block, and a strict CI/bootstrap run that must) read the same result.
60	export function report(probes) {
61	  const failures = probes.filter((p) => p.ok === false);
62	  const ran = probes.filter((p) => p.ok !== null).length;
63	  return {
64	    ok: failures.length === 0,
65	    ran,
66	    skipped: probes.length - ran,
67	    failures,
68	    summary: failures.length
69	      ? `Claudinite self-test: ${failures.length} of ${ran} probes FAILED — ${failures.map((f) => f.id).join(', ')}`
70	      : `Claudinite self-test: ${ran} probes passed.`,
71	  };
72	}
73	
74	// --- the probes ------------------------------------------------------------
75	// Each takes an injected `io` ({ exists, read, dirs, resolves }) so the whole
76	// set runs against an in-memory tree in tests. No probe imports another's
77	// result: a broken mount must not cascade into eight confusing failures, so
78	// each says one true thing about the repo in front of it.
79	
80	export function probeMount(io) {
81	  if (!io.exists(MOUNT)) return skip('mount', 'no vendored mount — this is the canon itself, or a repo that has not adopted');
82	  if (!io.exists(`${MOUNT}/engine/checks/check_the_world.mjs`)) {
83	    return fail('mount', `${MOUNT} exists but carries no engine`, 're-run the update task, or bootstrap this repo — the mount is incomplete');
84	  }
85	  return pass('mount');
86	}
87	
88	export function probeStamp(io) {
89	  const name = SETTINGS_FILES.find((f) => io.read(f) !== null) ?? CHECKS;
90	  const raw = io.read(name);
91	  if (raw === null) return fail('stamp', `${CHECKS} is missing`, 'run bootstrap --init to write the declaration');
92	  let cfg;
93	  try { cfg = JSON.parse(raw); } catch (e) {
94	    return fail('stamp', `${name} is not valid JSON: ${e.message}`, 'fix the JSON syntax — nothing can read the declaration until it parses');
95	  }
96	  if (!io.exists(MOUNT)) return skip('stamp', 'no vendored mount to stamp');
97	  // The VERSIONS, not a datetime. The `claudinite.updated` this probed until #1252
98	  // recorded the last full re-vendor rather than the last converge, so it was a
99	  // stale reading of a healthy mount; what the update flows actually read to decide
100	  // what to apply is what a member has installed, which is what must be present.
101	  if (!hasInstalledMount(cfg)) {
102	    return fail('stamp', 'the mount is present but no installed versions are recorded',
103	      'the update flows read these to decide what to apply — with none, the task self-skips forever (#518)');
104	  }
105	  return pass('stamp');
106	}
107	
108	// The #555 probe. A manifest the loader rejects means that pack's rules never
109	// run — silently, because normalizeManifest rebuilds `rules` from the scoped
110	// lists and an unvalidated manifest contributes none.
111	export function probePackManifests(loaded) {
112	  if (!loaded) return skip('pack-manifests', 'the pack loader could not be reached from here');
113	  if (loaded.errors?.length) {
114	    const first = loaded.errors[0];
115	    return fail('pack-manifests', `${loaded.errors.length} pack(s) failed to load or validate — first: ${first.what ?? first}`,
116	      first.fix ?? 'fix the manifest — a pack that does not validate contributes no rules, so its checks stop running with no other symptom');
117	  }
118	  if (!loaded.packs?.length) return fail('pack-manifests', 'no packs were discovered at all', 'check the mount and the declaration — a session with no packs enforces nothing');
119	  return pass('pack-manifests');
120	}
121	
122	export function probeHookTargets(io) {
123	  const raw = io.read(SETTINGS);
124	  if (raw === null) return skip('hook-targets', 'no .claude/settings.json');
125	  let cfg;
126	  try { cfg = JSON.parse(raw); } catch (e) {
127	    return fail('hook-targets', `${SETTINGS} is not valid JSON: ${e.message}`, 'fix the JSON — the harness silently runs no hooks when its settings will not parse');
128	  }
129	  const missing = [];
130	  for (const entries of Object.values(cfg.hooks ?? {})) {
131	    for (const entry of Array.isArray(entries) ? entries : []) {
132	      for (const hook of entry.hooks ?? []) {
133	        const cmd = String(hook.command ?? '');
134	        // The path inside the command, with the harness's variable resolved.
135	        const m = cmd.match(/\$CLAUDE_PROJECT_DIR\/(\S+)/);
136	        if (m && !io.exists(m[1])) missing.push(m[1]);
137	      }
138	    }
139	  }
140	  if (missing.length) {
141	    return fail('hook-targets', `${missing.length} hook command(s) point at files that do not exist: ${missing.join(', ')}`,
142	      're-run the update task to converge the wiring — a hook whose target is missing fails silently every session (#397)');
143	  }
144	  return pass('hook-targets');
145	}
146	
147	export function probeSkillLinks(io) {
148	  const root = '.claude/skills';
149	  if (!io.exists(root)) return skip('skill-links', 'no mounted skills');
150	  const dangling = io.dangling(root);
151	  if (dangling.length) {
152	    return fail('skill-links', `${dangling.length} mounted skill link(s) dangle: ${dangling.slice(0, 5).join(', ')}`,
153	      're-run the skill mount (the update task does it) — a dangling link is a skill the session cannot load (#424)');
154	  }
155	  return pass('skill-links');
156	}
157	
158	export function probeScheduler(io) {
159	  const text = io.read(SCHEDULER);
160	  if (text === null) return skip('scheduler', 'no vendored scheduler workflow — this repo has not cut over to per-project scheduling');
161	  const crons = [...text.matchAll(/cron:\s*['"]?([^'"\n]+?)['"]?\s*$/gm)].map((m) => m[1].trim());
162	  if (crons.length !== 1) {
163	    return fail('scheduler', `the scheduler declares ${crons.length} cron schedules, expected exactly one`, 'keep a single hourly cron — the scheduler is the repo\'s only cron');
164	  }
165	  const parts = crons[0].split(/\s+/);
166	  if (parts.length !== 5 || !Number.isInteger(Number(parts[0]))) {
167	    return fail('scheduler', `the scheduler cron "${crons[0]}" does not parse as a 5-field expression with a fixed minute`,
168	      'set "<minute> * * * *" with the repo-hashed minute — an unparseable cron means the repo never runs a task again');
169	  }
170	  return pass('scheduler');
171	}
172	
173	export function probeMigrations(migrations) {
174	  if (migrations === null) return skip('migrations', 'no migrations registry reachable from here');
175	  if (migrations instanceof Error) {
176	    return fail('migrations', `the migrations registry failed to load: ${migrations.message}`,
177	      'a malformed record aborts every update run — fix or remove it');
178	  }
